package com.harish.student_management.entity; import jakarta.persistence.*; import lombok.*; @Entity @Table(name="pickup_points") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class PickupPoint { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="route_id",nullable=false) BusRoute route; @Column(nullable=false,length=150) String name; @Column(length=255) String address; @Column Integer sequence; @Column(length=20) String pointType; }
